import { APP_NAME } from "@/lib/constants";
import { LOGO_ATAL, LOGO_MART, LOGO_REG, LOGO_SKEW } from "./logo-paths";

/**
 * Atalmart® registered wordmark — Vivek's exact artwork (Helvetica-Bold,
 * "Atal" #ff6b03 with a slight skew, "mart" #008236, ® top-right).
 *
 * Rendered from OUTLINES (src/components/ui/logo-paths.ts, generated by
 * scripts/brand/build-wordmark.mjs from the real Helvetica), not <text>:
 * Android has no Helvetica and used to fall back to Arial, which changed the
 * letterforms. Scaled to the parent font-size (height ≈ 1em), so call sites
 * keep using text-* classes. Source also at public/logo.svg.
 *
 * `onDark` swaps "mart" + ® to cream so the green doesn't lose contrast on the
 * brown footer / admin sidebar / boards. "Atal" saffron reads on both.
 */
export function Logo({
  className = "",
  registered = true,
  onDark = false,
}: {
  className?: string;
  registered?: boolean;
  onDark?: boolean;
}) {
  const mart = onDark ? "#FFFAF5" : "#008236";
  const reg = onDark ? "#FFFAF5" : "#1A1A1A";
  return (
    <span
      className={`inline-block leading-none ${className}`}
      role="img"
      aria-label={APP_NAME}
    >
      <svg
        // Original 400×100 artwork box (not the tight ink box) so the logo
        // keeps exactly the size it has always had at every call site.
        viewBox="0 0 400 100"
        style={{ height: "1.15em", width: "auto", display: "block" }}
        xmlns="http://www.w3.org/2000/svg"
        aria-hidden="true"
      >
        <g
          transform={LOGO_SKEW}
          fill="#ff6b03"
          dangerouslySetInnerHTML={{ __html: LOGO_ATAL }}
        />
        <g fill={mart} dangerouslySetInnerHTML={{ __html: LOGO_MART }} />
        {registered && (
          <g fill={reg} dangerouslySetInnerHTML={{ __html: LOGO_REG }} />
        )}
      </svg>
    </span>
  );
}
